INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'geometria-corporal-en-movimiento', 'Geometría Corporal en Movimiento', 'Dinámica de coordinación kinésica y transformación espacial donde los scouts se desplazan al ritmo de aplausos ensamblando figuras colectivas en movimiento.', '<h2>📜 Descripción de Geometría Corporal en Movimiento</h2>
<p><b>Geometría Corporal en Movimiento</b> es una dinámica scout de motricidad rítmica, esquema corporal y cooperación espacial. En esta actividad, los beneficiarios se desplazan por el campo al compás de palmadas, un pandero o canciones de campamento. A la señal del dirigente (ej. <i>''¡Grupos de 4... un automóvil en marcha!''</i> o <i>''¡Grupos de 3... un puente de madera!''</i>), los participantes deben agruparse instantáneamente en el número indicado y acoplar sus cuerpos para construir la estructura ordenada. Posteriormente, a una nueva señal, deben transformar lentamente su figura en otra modificando progresivamente sus segmentos corporales.</p>
<p>Esta dinámica ejercita la agilidad mental, el trabajo en equipo y el control cinético en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega Geometría Corporal en Movimiento?</h2>
<p>Para llevar a cabo la dinámica con fluidez y coordinación, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Desplazamiento Rítmico:</b> Todos los participantes caminan o trotan dispersos por la pista al ritmo del aplauso o pandero del animador.</li>
  <li><b>La Proclamación del Número y la Figura:</b> El dirigente detiene el ritmo y grita la indicación (ej. <i>''¡Grupos de tres... forman una casa!''</i>).</li>
  <li><b>Ensamblaje Instantáneo:</b> Los scouts buscan rápidamente a dos compañeros para formar el trío y combinan sus brazos, piernas y postura para armar la casa.</li>
  <li><b>La Metamorfosis Corporal:</b> Sin deshacer el grupo, el dirigente ordena: <i>''¡Ahora transformen la casa en un barco navegando!''</i>. Los integrantes deben alterar sus segmentos corporales de forma fluida hasta completar la nueva figura.</li>
  <li><b>Reinicio del Ritmo:</b> Se reanuda el desplazamiento rítmico y se varían los números de grupo y las estructuras requeridas.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de Geometría Corporal en Movimiento</h2>
<p>La dinámica premia la rapidez de integración y la plasticidad del ensamble en el Tally:</p>
<ul>
  <li><b>Metamorfosis Más Fluida:</b> Otorgar 5 puntos al grupo que realice la transición de una figura a otra con mayor coordinación.</li>
  <li><b>Rapidez de Agrupación:</b> Otorgar 3 puntos a los participantes que logren formar el número de grupo sin dejar compañeros aislados.</li>
  <li><b>Creatividad de Forma:</b> Otorgar 3 puntos al trío o equipo que diseñe la estructura corporal más original.</li>
</ul>', '/uploads/geometria-corporal-en-movimiento.webp', 'publicado', '{"areas": ["sociabilidad", "corporalidad", "creatividad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Exterior"], "materiales": ["Sin Materiales"], "objetivos": ["Servir activamente en su comunidad y cooperar con el grupo", "Desarrollo de la motricidad rítmica y esquema corporal", "Estimular la agilidad mental e improvisación", "Favorecer el trabajo en equipo"], "justificacion_areas": "Geometría Corporal en Movimiento fortalece la sociabilidad al ejercitar la inclusión activa y la disposición constante a acoplarse con cualquier compañero del grupo. Desarrolla la corporalidad afinando el ritmo, la agilidad de desplazamiento y el control de los segmentos corporales durante el movimiento. Estimula la creatividad a través de la resolución espacial inmediata de estructuras geométricas con el propio cuerpo.", "variaciones": "<b>Geometría Rítmica de Campamento:</b> Representar exclusivamente construcciones scouts (ej. carpa canadiense, mesa de altar, bálago o puente de troncos).<br><b>Figuras con Movimiento Cinético Colectivo:</b> Toda la clase se une en un solo gran grupo para formar un gigantesco mecanismo único (ej. una locomotora a vapor).<br><b>Geometría Silenciosa:</b> Realizar todas las agrupaciones e instrucciones en absoluto silencio utilizando claves de señas con las manos.", "recomendaciones": "Mantener una vigilancia atenta sobre el espacio para evitar colisiones durante la búsqueda acelerada de compañeros. Fomentar una actitud inclusiva para que los grupos acojan de inmediato al scout más cercano sin hacer distinciones de afinidad previa. Adaptar la velocidad del ritmo según la edad.", "objetivos_educativos": [{"id": "201cf9be-ca1f-40c4-a20a-ee589346e863", "area": "Sociabilidad", "unidad": "Manada", "texto": "Ayudo en mi casa tan pronto como me lo piden.", "como_se_cumple": "Integrándome con prontitud y entusiasmo al grupo para ayudar a completar la figura corporal."}, {"id": "3b6cf976-db3d-479e-b214-f165bf311a5f", "area": "Sociabilidad", "unidad": "Manada", "texto": "Ayudo siempre en las tareas que hay que hacer en mi casa y en la escuela.", "como_se_cumple": "Colaborando activamente en el ensamblaje de la figura con todos mis compañeros de la seisena."}, {"id": "e6645d74-6f5c-4151-b036-d52b621a101f", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Participo en las actividades de servicio que organiza mi patrulla.", "como_se_cumple": "Demostrando disposición de servicio y acogida inclusiva hacia cualquier integrante del equipo."}, {"id": "b3d92c8b-c7c8-42bc-bc03-4e925e019a87", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Propongo actividades de servicio de mi patrulla y Compañía y colaboro en su organización.", "como_se_cumple": "Coordinando con espíritu fraterno la distribución espacial para la metamorfosis corporal."}, {"id": "0d3b6b51-07ed-4d62-ba46-e68bab986e57", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Participo en las actividades de servicio que organiza mi patrulla.", "como_se_cumple": "Ofreciendo mi apoyo corporal para integrar a los compañeros en la estructura de la patrulla."}, {"id": "02b90ae6-edbc-4221-a9ec-4ac50d8b8b30", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Propongo actividades de servicio de mi patrulla y Tropa y colaboro en su organización.", "como_se_cumple": "Liderando con fraternidad y sentido comunitario la organización de la figura colectiva."}, {"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "unidad": "Manada", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Ejercitando la coordinación rítmica y el control de los segmentos corporales en carrera."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Manada", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Afinando el equilibrio kinésico y la agilidad de metamorfosis física."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "unidad": "Compañía", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Respetando las reglas de desplazamiento rítmico y acoplamiento seguro."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Exigiendo precisión y flexibilidad en la modificación progresiva de la postura."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "unidad": "Tropa", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Desarrollando la motricidad rítmica adaptativa en desplazamientos colectivos."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Perfeccionando el control kinesiológico de frenados y ensambles en movimiento."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando el ritmo del animador y las posiciones de los compañeros para ensamblar la figura."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Resolviendo con agilidad la disposición espacial necesaria para formar la estructura."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Expresando soluciones de diseño anatómico instantáneas en el equipo."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Visualizando la metamorfosis del objeto desde diferentes ángulos espaciales."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando agilidad de improvisación para transformar figuras en tiempo récord."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando geometrías corporales abstractas con máxima armonía visual."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

